import assert from'node:assert/strict';import type{GeneratedBody}from'../../src/core/generators/definition';import type{AnswerPart,PartAnswer}from'../../src/core/types';import facts from'./legacy-2018-pm-c-summary-facts.json';
/** Independent fixture mapping + signed BigInt semantics; no production imports. */
export function cSummaryEvent(w:number,v:number,m:number){const lo=-(2n**31n),hi=2n**31n-1n,p=BigInt(w)*BigInt(v);if(p<lo||p>hi)return{event:'overflow',stage:'multiply'};if(!m)return{event:'zero_division',stage:'divide'};const q=p/BigInt(m);if(q<lo||q>hi)return{event:'overflow',stage:'divide'};const i=BigInt(w)-q;if(i<lo||i>hi)return{event:'overflow',stage:'subtract'};if(i<0n||i>BigInt(w))return{event:'out_of_bounds',stage:i===BigInt(w+1)?'read_one_past':'pointer_formation',index:Number(i),quotient:Number(q)};return{event:'defined',index:Number(i),quotient:Number(q),stars:Number(q)};}
export function cSummaryStream(records:(string|number)[][],b:string,c:string){if(!records.length)return{status:'defined',rows:[]as unknown[][]};let[key,value]=records[0] as[string,number],count=1,ik:string|undefined,iv:number|undefined;const out:unknown[][]=[];const exec=(fragment:string)=>{for(const line of fragment.split('\n').map(s=>s.trim())){if(line==='count++;')count++;else if(line==='count--;')count--;else if(line==='value += inValue;'){if(iv===undefined)throw Error('uninitialized');value+=iv;}else if(line==='fprintf(outFile, format, key, count, value);')out.push([key,count,value]);else if(line==='fprintf(outFile, format, inKey, count, inValue);'){if(ik===undefined||iv===undefined)throw Error('uninitialized');out.push([ik,count,iv]);}else throw Error('unknown fragment');}};try{for(const row of records.slice(1)){[ik,iv]=row as[string,number];if(ik!==key){out.push([key,count,value]);key=ik;value=iv;count=1;}else exec(b);}exec(c);return{status:'defined',rows:out};}catch(e){assert.equal((e as Error).message,'uninitialized');return{status:'uninitialized_read',rows:out};}}
export function legacy2018CSummaryOracle(body:GeneratedBody,values:readonly number[]){const map=facts.mapping.find(m=>JSON.stringify(m.values)===JSON.stringify(values));assert(map,'INDEPENDENT_INPUT_MAPPING');const{w,u}=map,expected=facts.independent.program2.candidates.find(c=>c.input[0]===w&&c.input[1]===u)!;assert.equal(body.prompt.length,33);assert.equal(body.choices.length,15);assert.equal(body.answerParts?.length,6);assert.equal(body.partAnswers?.length,6);
 const units=facts.sourceUnits as unknown as{ id:string;kind:string;text?:string;caption?:string;headers?:string[];rows?:string[][];choices?:[string,string][];parts?:string[]}[];
 const group=(part:string)=>units.find(u=>u.kind==='answer_group'&&u.parts!.includes(part))!;
 assert.deepEqual(body.choices.slice(0,4).map(b=>(b[0]as{ text:string}).text),group('a').choices!.map(x=>x[1]));assert.deepEqual(body.choices.slice(4,9).map(b=>(b[0]as{text:string}).text),group('b').choices!.map(x=>x[1]));
 let bi=0;for(const row of facts.bodyMap.groups){if(row.target.startsWith('choices'))continue;const us=row.sourceUnits.map(id=>units.find(u=>u.id===id)!),b=body.prompt[bi++];if(us[0].kind==='figure'){assert.equal(b.type,'diagram');if(b.type!=='diagram')throw Error();assert.equal(b.scene.kind,'source_figure');if(b.scene.kind!=='source_figure')throw Error();const mode=us[0].id==='source-04'?1:us[0].id==='source-29'?3:w;assert.equal(b.scene.profile,us[0].id==='source-31'?'legacy-2018-c-summary-bar-print':'legacy-2018-c-summary-records');assert.deepEqual(b.scene.values,[mode]);continue;}
 if(us[0].kind==='table'){assert.equal(b.type,'table');if(b.type==='table'){assert.deepEqual(b.columns,us[0].headers);assert.deepEqual(b.rows,us[0].rows);}continue;}
 let text=us.map(u=>u.text!).join(us[0].kind.startsWith('code')?'\n':'');if(text.includes('void outListG')){text=text.replace('"'+'*'.repeat(25)+'"','"'+'*'.repeat(w)+'"').replace('25 - 25 * value / valueMax',`${w} - ${w} * value / valueMax`);}else if(text.includes('valueMaxを25個'))text=text.replace('valueMaxを25個',`valueMaxを${w}個`).replace('25×value÷valueMax',`${w}×value÷valueMax`);assert('text'in b);assert.equal(b.text,text);}
 const matrix=body.choices.slice(9).map((blocks,i)=>{assert.equal(blocks.length,1);const b=blocks[0];assert.equal(b.type,'table');if(b.type!=='table')throw Error();assert.deepEqual(b.columns,['valueの値','valueMaxの値']);assert.equal(b.rows.length,1);const pair=b.rows[0].map(x=>Number(x.replaceAll(',','')));assert.deepEqual(pair,expected.pairs[i]);const r=cSummaryEvent(w,pair[0],pair[1]);assert.equal(r.event,expected.evaluations[i].event);return r.event;});
 const fixedIndices=[1,2,1,...['overflow','zero_division','out_of_bounds'].map(event=>{const ids=matrix.flatMap((e,i)=>e===event?[i]:[]);assert.equal(ids.length,1);return ids[0];})],counts=[4,5,5,6,6,6],offsets=[0,4,4,9,9,9];
 for(let k=0;k<6;k++){const part:AnswerPart=body.answerParts![k];assert.equal(part.id,'part-'+'abcdef'[k]);assert.deepEqual(part.choiceIds,Array.from({length:counts[k]},(_,j)=>'choice-value-'+(offsets[k]+j+1)));const a:PartAnswer=body.partAnswers![k];assert(a.kind==='choice');assert.equal(a.partId,part.id);assert.equal(a.choiceId,part.choiceIds[fixedIndices[k]]);}
 const code=body.prompt.filter(b=>b.type==='code').map(b=>b.text);assert.equal(code.length,2);assert(code[0].includes("inKey[keyLen] = '\\0';"));assert(code[1].includes('valueMax = 0;'));assert(!JSON.stringify(body.prompt).includes('C99'));assert.match(body.explanation,new RegExp(String(w*10*u).replace(/\B(?=(\d{3})+(?!\d))/g,',')));return{w,u,events:matrix,starCounts:expected.figure5Stars,graphElements:w+1};
}
